#include <stdio.h>
#include <string.h>
#include <limits.h>

int ans;
char target[4][5];
char grid[4][5];

int min(int a, int b) {
    return a < b ? a : b;
}

void dfs(int r, int c, int cnt) {
    // if we've already used more presses than current best, prune
    if (cnt >= ans) return;

    // find the next cell that doesn't match the target
    int nr = -1, nc = -1;
    for (int i = r; i < 4; i++) {
        int start_j = (i == r) ? c : 0;
        for (int j = start_j; j < 4; j++) {
            if (grid[i][j] != target[i][j]) {
                nr = i;
                nc = j;
                break;
            }
        }
        if (nr != -1) break;
    }

    // if all cells match, update answer
    if (nr == -1) {
        ans = min(ans, cnt);
        return;
    }

    // try all possible stamps that cover (nr, nc) as the top-left corner
    // stamp dimensions: height from 1 to 4-nr, width from 1 to 4-nc
    for (int h = 1; h <= 4 - nr; h++) {
        for (int w = 1; w <= 4 - nc; w++) {
            // try all colors
            for (char color = 'R'; color <= 'G'; color++) {
                // skip if color would be wasted (no improvement)
                // we need at least one cell in the stamp to become correct
                int improves = 0;
                for (int i = nr; i < nr + h; i++) {
                    for (int j = nc; j < nc + w; j++) {
                        if (grid[i][j] != target[i][j] && target[i][j] == color) {
                            improves = 1;
                            break;
                        }
                    }
                    if (improves) break;
                }
                if (!improves) continue;

                // save old state
                char old[4][5];
                memcpy(old, grid, sizeof(grid));

                // apply stamp
                for (int i = nr; i < nr + h; i++) {
                    for (int j = nc; j < nc + w; j++) {
                        grid[i][j] = color;
                    }
                }

                dfs(nr, nc + 1, cnt + 1);

                // restore
                memcpy(grid, old, sizeof(grid));
            }
        }
    }
}

