}

int main(void) {
    int M;
    if (scanf("%d", &M) != 1) return 0;

    Stamp *stamps = (Stamp *)malloc(sizeof(Stamp) * M);
    for (int i = 0; i < M; i++) {
        scanf("%d %d", &stamps[i].h, &stamps[i].w);
    }

    char g[4][8];
    for (int i = 0; i < 4; i++) {
        scanf("%s", g[i]);
    }

    /* Build target masks for R, G, B */
    int target[3] = {0, 0, 0}; /* 0:R, 1:G, 2:B */
    for (int r = 0; r < 4; r++) {
        for (int c = 0; c < 4; c++) {
            int bit = 1 << (r * 4 + c);
            if (g[r][c] == 'R') target[0] |= bit;
            else if (g[r][c] == 'G') target[1] |= bit;
            else if (g[r][c] == 'B') target[2] |= bit;
        }
    }

    /* Generate all distinct masks obtainable by one press of any stamp */
    char *can = (char *)calloc(MAXS, 1);
    int *ops = (int *)malloc(sizeof(int) * MAXS);
    int opcnt = 0;

    for (int i = 0; i < M; i++) {
        int h = stamps[i].h, w = stamps[i].w;
        for (int dr = -h + 1; dr <= 3; dr++) {
            for (int dc = -w + 1; dc <= 3; dc++) {
                int mask = 0;
                for (int r = 0; r < h; r++) {
                    int rr = dr + r;
                    if (rr < 0 || rr >= 4) continue;
                    for (int c = 0; c < w; c++) {
                        int cc = dc + c;
                        if (cc < 0 || cc >= 4) continue;
                        mask |= 1 << (rr * 4 + cc);
                    }
                }
                if (!can[mask]) {
                    can[mask] = 1;
                    ops[opcnt++] = mask;
                }
            }
        }
    }

    /* dp[mask] = minimum presses to obtain exactly 'mask' as the set of cells
       whose final visible color is the current color, using only this color's presses.
       Transition: new = (old & ~op) | op = old | op, but because later presses of the
       same color don't hurt, we only need cover target exactly from empty by unions.
       Thus this becomes minimum number of operation masks whose union is target.
    */
    int *dp = (int *)malloc(sizeof(int) * MAXS);
    for (int color = 0; color < 3; color++) {
        for (int i = 0; i < MAXS; i++) dp[i] = INF;
        dp[0] = 0;

        int T = target[color];
        for (int mask = 0; mask < MAXS; mask++) {
            if (dp[mask] == INF) continue;
            if ((mask & ~T) != 0) continue; /* invalid state */
            for (int i = 0; i < opcnt; i++) {
                int op = ops[i];
                if ((op & ~T) != 0) continue; /* cannot paint outside target for final color */
                int nmask = mask | op;
                if (dp[nmask] > dp[mask] + 1) dp[nmask] = dp[mask] + 1;
            }
        }
        target[color] = dp[T];
    }

    int ans = target[0] + target[1] + target[2];
    printf("%d\n", ans);

    free(stamps);
    free(can);
    free(ops);
    free(dp);
    return 0;
}

