#include <bits/stdc++.h>
using namespace std;

// Represent the target grid as a bitmask of 16 cells, each cell has 2 bits for color:
// 00 = none, 01 = red, 10 = green, 11 = blue
// We'll store target as 32-bit integer (16 * 2 bits)
using State = uint32_t;

// Encode a 4x4 grid into a State
State encode(const vector<string>& grid) {
    State s = 0;
    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < 4; j++) {
            int col = 0;
            if (grid[i][j] == 'R') col = 1;
            else if (grid[i][j] == 'G') col = 2;
            else if (grid[i][j] == 'B') col = 3;
            s |= (col << (2 * (i * 4 + j)));
        }
    }
    return s;
}

// Precompute all possible stamp placements (rectangle shapes) on a 4x4 grid
// A stamp is defined by its shape (set of cells) and can be placed with any offset
// We'll generate all possible non-empty rectangular shapes, then for each shape,
// all placements (possibly partially off-grid) produce a mask of cells that get colored.
vector<State> stamp_masks;

void precompute_stamps() {
    // generate all rectangles: top-left (r1,c1) to bottom-right (r2,c2) inclusive
    for (int r1 = 0; r1 < 4; r1++) {
        for (int c1 = 0; c1 < 4; c1++) {
            for (int r2 = r1; r2 < 4; r2++) {
                for (int c2 = c1; c2 < 4; c2++) {
                    // shape mask (relative to top-left)
                    uint32_t shape = 0;
                    int h = r2 - r1 + 1;
                    int w = c2 - c1 + 1;
                    // For each possible placement on 4x4 grid (offset)
                    // The stamp can be placed such that it covers cells from (dr, dc) to (dr+h-1, dc+w-1)
                    // dr from -h+1 to 3, dc from -w+1 to 3
                    for (int dr = -h+1; dr <= 3; dr++) {
                        for (int dc = -w+1; dc <= 3; dc++) {
                            uint32_t mask = 0;
                            bool valid = false;
                            for (int r = 0; r < h; r++) {
                                for (int c = 0; c < w; c++) {
                                    int nr = dr + r;
                                    int nc = dc + c;
                                    if (nr >= 0 && nr < 4 && nc >= 0 && nc < 4) {
                                        mask |= (1u << (nr * 4 + nc));
                                        valid = true;
                                    }
                                }
                            }
                            if (valid) {
                                stamp_masks.push_back(mask);
                            }
                        }
                    }
                }
            }
        }
    }
    // Remove duplicates
    sort(stamp_masks.begin(), stamp_masks.end());
    stamp_masks.erase(unique(stamp_masks.begin(), stamp_masks.end()), stamp_masks.end());
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    precompute_stamps();

    vector<string> target(4);
    for (int i = 0; i < 4; i++) {
        cin >> target[i];
    }

    State goal = encode(target);

    // BFS from initial state (all zeros) to goal
    // State is 32-bit, but we only care about cells that have color in goal?
    // Actually we need to match exactly: each cell must have the correct color.
    // So we search over all possible states reachable by stamping.
    // Use BFS with queue, distance map.

    unordered_map<uint32_t, int> dist;
    queue<uint32_t> q;

    uint32_t start = 0;
    dist[start] = 0;
    q.push(start);

    // For each stamp, we can apply any color (1,2,3) to the mask area.
    // So for each stamp mask, we can generate 3 possible transitions.
    // But we can precompute for each mask the effect: new_state = (old_state & ~mask) | (color_mask)
    // where color_mask has the chosen color bits in the mask positions.
    // Since color is uniform for the whole stamp, we can precompute for each mask and each color.

    struct Transition {
        uint32_t apply_to; // mask of cells to change
        uint32_t color_val; // the 2-bit color value repeated in those cells
    };
    vector<Transition> trans;
    for (auto mask : stamp_masks) {
        for (int col = 1; col <= 3; col++) {
            uint32_t color_val = 0;
            for (int i = 0; i < 16; i++) {
                if (mask & (1u << i)) {
                    color_val |= (col << (2*i));
                }
            }
            trans.push_back({mask, color_val});
        }
    }

    while (!q.empty()) {
        uint32_t cur = q.front(); q.pop();
        int d = dist[cur];
        if (cur == goal) {
            cout << d << '\n';
            return 0;
        }
        for (auto &t : trans) {
            uint32_t nxt = (cur & ~t.apply_to) | t.color_val;
            // Actually careful: apply_to is the mask of cells that the stamp covers.
            // But the stamp colors those cells with its color, overwriting whatever was there.
            // So new state = (cur & ~mask) | (color_mask)
            // where mask is the set of cells covered (we have apply_to = mask of cells)
            // and color_mask is the color bits in those cells.
            // But t.apply_to is exactly the mask of cells? In our struct we stored apply_to as mask.
            // However we also need to clear those cells before ORing.
            uint32_t nxt_state = (cur & ~t.apply_to) | t.color_val;
            if (!dist.count(nxt_state)) {
                dist[nxt_state] = d + 1;
                q.push(nxt_state);
            }
        }
    }

    // Should never reach here
    cout << -1 << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

/*
We have a 4x4 board. Each press paints an axis-aligned rectangle of one chosen color
(R/G/B), clipping outside the board. Later presses overwrite earlier ones.

Input (inferred from statement):
- 4 lines describing the target 4x4 coloring using characters R,G,B.
- an integer n
- n lines: hi wi   (stamp sizes, no rotation allowed)

Goal: minimum number of presses to obtain the target exactly.

Approach:
Dynamic programming over subsets of cells already "fixed" from top to bottom layer.

Think in reverse:
Choose the topmost press first. It must paint some rectangle with one color c, and all
cells of that rectangle that remain visible in the final picture must have color c.
Some cells in the rectangle may be covered later (in forward time), i.e. already fixed
in reverse DP.

State mask: cells already accounted for by top layers.
Transition: choose a rectangle obtainable by some stamp size (possibly clipped by board),
and a color c, such that every newly added cell in the rectangle has target color c.
Then add all cells of the rectangle to mask, cost +1.
Answer: dp[0], with dp[full]=0.

Why sufficient:
Any actual sequence, viewed from last press to first, yields such transitions.
Conversely, any reverse construction corresponds to a valid forward sequence.

There are only 16 cells, so 2^16 states. Rectangles on 4x4 are few.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> g(4);
    for (int i = 0; i < 4; ++i) {
        if (!(cin >> g[i])) return 0;
    }

    int n;
    cin >> n;
    vector<pair<int,int>> stamps(n);
    for (int i = 0; i < n; ++i) cin >> stamps[i].first >> stamps[i].second;

    auto colorId = [&](char ch) {
        if (ch == 'R' || ch == 'r') return 0;
        if (ch == 'G' || ch == 'g') return 1;
        return 2; // B/b
    };

    int cellColor[16];
    for (int r = 0; r < 4; ++r)
        for (int c = 0; c < 4; ++c)
            cellColor[r * 4 + c] = colorId(g[r][c]);

    // Generate all distinct clipped rectangles achievable by at least one stamp.
    // A press places top-left of the stamp at any integer position, even outside board.
    // The visible part is any intersection of board with [x, x+h-1] x [y, y+w-1].
    // For fixed h,w and placement, visible part is any non-empty rectangle with
    // height <= h and width <= w.
    set<int> rectSet;
    for (auto [h, w] : stamps) {
        for (int r1 = 0; r1 < 4; ++r1) {
            for (int r2 = r1; r2 < 4; ++r2) {
                int hh = r2 - r1 + 1;
                if (hh > h) continue;
                for (int c1 = 0; c1 < 4; ++c1) {
                    for (int c2 = c1; c2 < 4; ++c2) {
                        int ww = c2 - c1 + 1;
                        if (ww > w) continue;
                        int mask = 0;
                        for (int r = r1; r <= r2; ++r)
                            for (int c = c1; c <= c2; ++c)
                                mask |= 1 << (r * 4 + c);
                        rectSet.insert(mask);
                    }
                }
            }
        }
    }

    vector<int> rects(rectSet.begin(), rectSet.end());

    // Precompute whether a rectangle can be painted as topmost visible color c
    // on the cells not yet covered: i.e. among the cells newly added, all must be color c.
    const int FULL = (1 << 16) - 1;
    const int INF = 1e9;
    vector<int> dp(1 << 16, INF);
    dp[FULL] = 0;

    for (int mask = FULL - 1; mask >= 0; --mask) {
        for (int rect : rects) {
            int add = rect & (~mask);
            if (add == 0) continue;

            int first = __builtin_ctz(add);
            int c = cellColor[first];
            bool ok = true;
            int x = add;
            while (x) {
                int b = __builtin_ctz(x);
                if (cellColor[b] != c) {
                    ok = false;
                    break;
                }
                x &= x - 1;
            }
            if (!ok) continue;

            dp[mask] = min(dp[mask], 1 + dp[mask | rect]);
        }
    }

    cout << dp[0] << '\n';
    return 0;
}

