        return [(r*4+c) for r in range(r1, r2+1) for c in range(c1, c2+1)]

    rect_cells = [cells_of(*r) for r in rectangles]

    # DFS: assigned is a list of 16 elements, -1 = unassigned
    # We place stamps from last to first
    # Find first unassigned cell, try all rectangles covering it with all colors

    def dfs(assigned, depth):
        # Find first unassigned
        first = -1
        for i in range(16):
            if assigned[i] == -1:
                first = i
                break
        if first == -1:
