        int targetState = encode(target);

        // BFS
        Queue<Integer> queue = new LinkedList<>();
        Map<Integer, Integer> dist = new HashMap<>();
        queue.add(startState);
        dist.put(startState, 0);

        while (!queue.isEmpty()) {
            int curState = queue.poll();
            int curDist = dist.get(curState);
            if (curState == targetState) {
                System.out.println(curDist);
                return;
            }

            // Decode current grid
            char[][] grid = decode(curState);

            // Try applying each stamp with each color
            for (int[] stamp : stamps) {
                int r1 = stamp[0], c1 = stamp[1], r2 = stamp[2], c2 = stamp[3];
                // For each color: R, G, B
                for (int color = 1; color <= 3; color++) {
                    char colChar = colorToChar(color);
                    // Apply stamp: only cells within grid are affected
                    char[][] newGrid = new char[4][4];
                    for (int i = 0; i < 4; i++) {
                        System.arraycopy(grid[i], 0, newGrid[i], 0, 4);
                    }
                    // Stamp area (clipped to grid)
                    int sr = Math.max(0, r1);
                    int er = Math.min(3, r2);
                    int sc = Math.max(0, c1);
                    int ec = Math.min(3, c2);
                    for (int r = sr; r <= er; r++) {
                        for (int c = sc; c <= ec; c++) {
                            newGrid[r][c] = colChar;
                        }
                    }
                    int newState = encode(newGrid);
                    if (!dist.containsKey(newState)) {
                        dist.put(newState, curDist + 1);
                        queue.add(newState);
                    }
                }
            }
        }

        // Should never reach here if target is reachable (it always is)
        System.out.println(-1);
    }

    // Encode 4x4 grid into an int: 2 bits per cell, row-major order
    static int encode(char[][] grid) {
        int state = 0;
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                int val = charToVal(grid[i][j]);
                state |= (val << (2 * (i * 4 + j)));
            }
        }
        return state;
    }

    // Decode int back to char grid
    static char[][] decode(int state) {
        char[][] grid = new char[4][4];
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                int val = (state >> (2 * (i * 4 + j))) & 3;
                grid[i][j] = valToChar(val);
            }
        }
        return grid;
    }

    static int charToVal(char c) {
        switch (c) {
            case '.': return 0;
            case 'R': return 1;
            case 'G': return 2;
            case 'B': return 3;
            default: return 0;
        }
    }

    static char valToChar(int v) {
        switch (v) {
            case 0: return '.';
            case 1: return 'R';
            case 2: return 'G';
            case 3: return 'B';
            default: return '.';
        }
    }

    static char colorToChar(int color) {
        switch (color) {
            case 1: return 'R';
            case 2: return 'G';
            case 3: return 'B';
            default: return '.';
        }
    }
}

import java.util.*;

public class Main {
    static char[] target = new char[16];
    static int limit;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        for (int i = 0; i < 4; i++) {
            String line = sc.next();
            for (int j = 0; j < 4; j++) target[i*4+j] = line.charAt(j);
        }
        for (limit = 0; limit <= 16; limit++) {
            boolean[] done = new boolean[16];
            for (int i = 0; i < 16; i++) if (target[i] == '.') done[i] = true;
            if (dfs(done, 0)) { System.out.println(limit); return; }
        }
    }
    static boolean dfs(boolean[] done, int depth) {
        int first = -1;
        for (int i = 0; i < 16; i++) if (!done[i]) { first = i; break; }
        if (first == -1) return true;
        if (depth == limit) return false;
        char color = target[first];
        int fr = first/4, fc = first%4;
        for (int r1=0;r1<=fr;r1++) for (int r2=fr;r2<4;r2++)
         for (int c1=0;c1<=fc;c1++) for (int c2=fc;c2<4;c2++) {
            boolean[] nd = done.clone();
            boolean ok = true;
            for (int r=r1;r<=r2&&ok;r++) for (int c=c1;c<=c2&&ok;c++) {
                int idx=r*4+c;
                if (!nd[idx]) { if(target[idx]!=color) ok=false; else nd[idx]=true; }
            }
            if (ok && dfs(nd, depth+1)) return true;
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

/*
We need the minimum number of stamp presses to obtain a target 4x4 coloring
using given rectangular stamp sizes. Each press paints an axis-aligned rectangle
(with one of 3 colors), possibly partially outside the 4x4 board; only the
intersection matters. Later presses overwrite earlier ones.

Key observation:
Consider the last press. It paints some rectangle R (intersection with board),
all with one color c, and in the final picture every cell of R must be c.
Thus R must be a monochromatic rectangle in the target picture, and it must be
obtainable as the intersection of the 4x4 board with one of the available stamp
sizes placed somewhere.

Then:
dp[mask] = minimum presses to paint exactly the set of cells in mask correctly,
where colors are those from the target.
Transition:
Choose a valid final rectangle submask S contained in mask, monochromatic,
paintable by some stamp. Then
dp[mask] = min(dp[mask ^ S] + 1).

Since board has 16 cells, mask size is 2^16 = 65536, feasible.
We precompute all distinct valid rectangle masks obtainable from the stamps.
*/

public class Main {
    static final int H = 4, W = 4, N = 16, FULL = (1 << 16) - 1;
    static final int INF = 1_000_000_000;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int m;
        if (!fs.hasNext()) return;
        m = fs.nextInt();

        boolean[] possible = new boolean[17 * 17]; // index a*17+b for 1..4 dims only used
        int[] sh = new int[m];
        int[] sw = new int[m];
        for (int i = 0; i < m; i++) {
            sh[i] = fs.nextInt();
            sw[i] = fs.nextInt();
        }

        char[][] g = new char[H][W];
        for (int i = 0; i < H; i++) {
            String s = fs.next();
            while (s.length() < 4) s += fs.next(); // safety if spaced strangely
            g[i] = s.toCharArray();
        }

        // All distinct rectangle masks obtainable as intersection of board with some stamp placement.
        ArrayList<Integer> rectMasks = new ArrayList<>();
        boolean[] seenRect = new boolean[1 << 16];

        for (int idx = 0; idx < m; idx++) {
            int a = sh[idx], b = sw[idx];
            // Top-left of stamp can be from -(a-1)..3 and -(b-1)..3
            for (int r0 = -a + 1; r0 <= H - 1; r0++) {
                for (int c0 = -b + 1; c0 <= W - 1; c0++) {
                    int r1 = Math.max(0, r0);
                    int c1 = Math.max(0, c0);
                    int r2 = Math.min(H - 1, r0 + a - 1);
                    int c2 = Math.min(W - 1, c0 + b - 1);
                    if (r1 > r2 || c1 > c2) continue;
                    int mask = 0;
                    for (int r = r1; r <= r2; r++) {
                        for (int c = c1; c <= c2; c++) {
                            mask |= 1 << (r * 4 + c);
                        }
                    }
                    if (!seenRect[mask]) {
                        seenRect[mask] = true;
                        rectMasks.add(mask);
                    }
                }
            }
        }

        // Keep only monochromatic rectangles in the target; these can be the last press.
        ArrayList<Integer> valid = new ArrayList<>();
        for (int mask : rectMasks) {
            char col = 0;
            boolean ok = true;
            for (int i = 0; i < 16; i++) {
                if (((mask >> i) & 1) == 1) {
                    char cur = g[i / 4][i % 4];
                    if (col == 0) col = cur;
                    else if (col != cur) {
                        ok = false;
                        break;
                    }
                }
            }
            if (ok) valid.add(mask);
        }

        int[] dp = new int[1 << 16];
        Arrays.fill(dp, INF);
        dp[0] = 0;

        for (int mask = 1; mask <= FULL; mask++) {
            for (int rmask : valid) {
                if ((rmask & mask) == rmask) {
                    dp[mask] = Math.min(dp[mask], dp[mask ^ rmask] + 1);
                }
            }
        }

        System.out.println(dp[FULL]);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        boolean hasNext() throws IOException {
            int c;
            while ((c = read()) != -1 && c <= ' ') {}
            if (c == -1) return false;
            ptr--;
            return true;
        }

        String next() throws IOException {
            int c;
            while ((c = read()) != -1 && c <= ' ') {}
            StringBuilder sb = new StringBuilder();
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            while ((c = read()) != -1 && c <= ' ') {}
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}
